window.VO = [{"id":"n01","text":"Your partner in crime is in the next room.","at":0.08,"t0":0.04,"t1":2.195},{"id":"n02","text":"And he's talking.","at":6.49,"t0":3.245,"t1":4.345},{"id":"d01","text":"Whoever talks walks out tonight.","at":9.69,"t0":4.845,"t1":7.35},{"id":"d02","text":"The other one does ten years.","at":15.3,"t0":7.65,"t1":9.92},{"id":"d03","text":"You both talk? Five each.","at":21.34,"t0":10.67,"t1":12.82},{"id":"n03","text":"If nobody talks, a year each.","at":26.34,"t0":13.17,"t1":15.045},{"id":"n04","text":"Stay silent, or talk?","at":32.99,"t0":16.495,"t1":17.85},{"id":"f01","text":"Nah. My partner won't talk.","at":38.3,"t0":19.15,"t1":20.68},{"id":"f02","text":"I'd bet ten years on it.","at":41.96,"t0":20.98,"t1":22.5},{"id":"n05","text":"He was talking about you.","at":46.1,"t0":23.05,"t1":24.415},{"id":"n06","text":"If you stayed silent, you both do a year.","at":49.83,"t0":24.915,"t1":27.23},{"id":"n07","text":"If you talked, you walk out tonight, and he does the ten.","at":55.36,"t0":27.68,"t1":30.515},{"id":"n08","text":"For trusting you.","at":61.73,"t0":30.865,"t1":31.875},{"id":"n09","text":"Talking was the safe move.","at":65.85,"t0":32.925,"t1":34.48},{"id":"n10","text":"That's the deal.","at":69.56,"t0":34.78,"t1":35.7},{"id":"n11","text":"It doesn't need a bad friend.","at":72.7,"t0":36.35,"t1":37.87},{"id":"n12","text":"It just needs you to doubt a good one.","at":76.34,"t0":38.17,"t1":39.97},{"id":"n13","text":"Now try it on your partner in crime.","at":83.34,"t0":41.67,"t1":43.65},{"id":"n14","text":"And don't warn them.","at":87.9,"t0":43.95,"t1":45.05},{"id":"n15","text":"Unless they just tried it on you.","at":91.3,"t0":45.65,"t1":47.24},{"id":"n16","text":"Next case.","at":95.88,"t0":47.94,"t1":48.845}];
